INSERT INTO `revista` (`id`, `titulo`, `capa`, `visualizar`, `download`, `sobre`, `icone`) VALUES
(1, '1º Edição - Revista PET Computação', './assets/revistas/1a_edicao/revista_1a_edicao_capa.png', 'https://online.fliphtml5.com/hyccq/wkkw/', '/assets/revistas/1a_edicao/revista_1a_Edicao.pdf', 'O Programa de Educação Tutorial em Computação (PETComp) disponibiliza a revista PETComp, com o objetivo de divulgar ao público os variados projetos nos quais nosso PET está envolvido. Os leitores terão acesso a diversos artigos, além de notícias sobre eventos e outras iniciativas do grupo. Publicada no primeiro semestre de 2024, a primeira edição da revista já pode ser acessada.', './assets/revistas/1a_edicao/revista_1a_Edicao_Icone.svg'),
(2, '2º Edição - Revista PET Computação', './assets/revistas/2a_edicao/revista_2a_edicao_capa.png', 'https://online.fliphtml5.com/kikwh/antd/', '/assets/revistas/2a_edicao/revista_2a_Edicao.pdf', 'O Programa de Educação Tutorial em Computação (PETComp) disponibiliza a revista PETComp, com o objetivo de divulgar ao público os variados projetos nos quais nosso PET está envolvido. Os leitores terão acesso a diversos artigos, além de notícias sobre eventos e outras iniciativas do grupo. Publicada no segundo semestre de 2024, a segunda edição da revista já pode ser acessada.', './assets/revistas/2a_edicao/revista_2a_Edicao_Icone.svg');
INSERT INTO `trabalhos_publicados` (`id`, `titulo`, `autor`, `ano`, `palavras_chave`, `resumo`, `link`) VALUES
(1, 'Artigo: De Veteranos para os Novatos: Avaliação das Atividades de Recepção aos Calouros Organizado pelo Grupo PETComp', 'Daniel Pinto, Eduarda Chagas, Gabriel Costa, Kennedy Nunes, Ricardo Anchieta, Simara Rocha, Anselmo Paiva, Luis Rivero', '2020', NULL, 'Alunos ingressantes em cursos de ensino superior sentem dificuldade em se adaptar à nova modalidade de ensino. Nesse contexto, o evento da Semana do Calouro é realizado pelos discentes do grupo PET de Ciência da Computação da Universidade Federal do Maranhão acompanhados por professores como uma atividade de integração aos novos discentes do curso de Ciência da Computação. Este artigo relata a experiência de aplicar diversas atividades com o intuito de esclarecer as dúvidas geradas pelo ingresso no novo ambiente, bem como aumentara visibilidade dos contextos do curso. Ao término das atividades, o feedback dos discentes apontou para a utilidade das mesmas para conhecer as oportunidades dentro da universidade em termos de projetos, pesquisas e áreas de atuação, assim como soluções para problemas que surgiram durante sua execução.', 'https://sol.sbc.org.br/index.php/wei/article/view/11130/11001'),
(2, 'Artigo: Identificando as Atividades dos Grupos do Programa de Educação Tutorial na Área de Computação no Apoio à Inclusão e Alfabetização Digital', 'Emily Costa, Antônio Pinto, José Ribamar Durand Rodrigues Junior, Alana Araújo, Ednara Pereira, Geraldo Braz Junior, Rodrigo Santos, Luis Rivero', '2019', NULL, 'O Programa de Educação Tutorial (PET) tem o objetivo de incentivar grupos de alunos de graduação a desenvolver atividades relacionadas com o Ensino, a Pesquisa e a Extensão. Existem 37 grupos PET listados no site da SBC que realizam atividades voltadas para a comunidade (público externo à universidade, idosos, crianças, entre outros). Este artigo apresenta uma análise de quais das atividades divulgadas por estes grupos são voltadas para o apoio à inclusão e alfabetização digital. As informações sobre casos de sucesso destas atividades podem servir como base para outros grupos e incentivar parcerias para realizar atividades afins.', 'https://br-ie.org/pub/index.php/wie/article/view/8594'),
(3, 'Artigo: Identificação das Expectativas e Dificuldades de Alunos de Graduação no Ensino de Engenharia de Software', 'Jéssica Mendes, Yandson Costa, Kastney Frazão, Rodrigo Santos, Davi Santos, Luis Rivero', '2019', NULL, 'A  Engenharia  de  Software  visa  apoiar  o  desenvolvimento  de  sistemas computacionais de qualidade, reduzindo os custos de produção e aumentando a produtividade dos profissionais. Buscar entender as necessidades dos alunos iniciantes  nessa  área  da  computação  é  vital  para  propor  metodologias adequadas  de  ensino.  Este  artigo  apresenta  o  resultado  da  aplicação  de  um questionário quanto à experiência dos alunos de uma disciplina introdutória de Engenharia de Software. Foi capturada a expectativa de alunos que ainda não cursaram  a  disciplina,  assim  como  a  visão  de  alunos  que  já  a  cursaram, reprovando  ou  não.  Os  resultados  desta  pesquisa  permitiram  identificar eventuais aspectos que possam ter influência positiva ou negativa no processo de aprendizado.', 'https://sol.sbc.org.br/index.php/wei/article/view/6640/6536'),
(4, 'Artigo: Educação Tutorial em Computação: Uma Análise Retrospectiva das Atividades Realizadas para a Formação Pessoal e Profissional de Cientistas da Computação', 'Fernando Leite, Gabriel Cardoso, Yandson Costa, Igor Estrela, Antônio Pinto, Ednara Pereira, Geraldo Braz Júnior, Luis Rivero', '2019', NULL, 'O Programa de Educação Tutorial (PET) atua como uma iniciativa de promover a formação integrada de todos os atores envolvidos combatendo a evasão, estimulando o desenvolvimento criativo e empreendedor, assim como a continuação para níveis superiores de formação acadêmica. Apesar da existência de 37 grupos PET na área de computação segundo a Sociedade Brasileira de Computação (SBC), poucos grupos divulgam os resultados das ações realizadas em eventos científicos da computação para discutir suas implicações. Nesse contexto, este trabalho apresenta uma análise das atividades desenvolvidas em um grupo PET de Ciência da Computação do ponto de vista dos discentes. Os resultados apontam o impacto das atividades na formação dos alunos, lições aprendidas e oportunidades de melhoria para o sucesso das atividades.', 'https://sol.sbc.org.br/index.php/wei/article/view/6621/6517'),
(5, 'Resumo: SIEPET: Uma proposta de remodelagem de um sistema para novas necessidades acadêmicas', 'Gabriel Silva Monteles, Eduardo Roger Silva Nascimento, Diego da Silva Oliveira, Vinícius Augusto Cardoso Reis, Geraldo Braz Júnior', '2017', 'ENGENHARIA DE SOFTWARE, RECURSO, INTERFACE', 'O Programa de Educação Tutorial (PET) tem em seu escopo de desenvolvimento atividades de pesquisa, ensino e extensão que complementam a educação de seus alunos. Muitas dessas atividades resultam em criação de eventos abertos à comunidade acadêmica. Por sua vez, o gerenciamento destes eventos envolve inscrição, controle de frequência e emissão de certificados. Neste contexto, o PET Ciência da Computação (PETComp) desenvolveu o XSCERT, uma plataforma de eventos como forma de facilitar o gerenciamento de algumas atividades e aproximar os grupos PET da UFMA. Com o decorrer do tempo, novas necessidades surgiram, como a criação de sub-eventos dentro de um evento, eventos pagos e inscrições coletivas para eventos que possuem competições. De posse dessa necessidade, e também com o objetivo de criar uma proposta mais intuitiva e que possa ser compartilhada com os outros grupos, houve a iniciativa de reformular o antigo sistema de eventos do grupo. O sistema foi denominado de SIEPET (Sistema de Inscrições em Eventos do PET).', 'https://petcompufma.org/documents/SIEPET-Uma-proposta-de-remodelagem-de-um-sistema-para-novas-necessidades-acadêmicas.pdf'),
(6, 'Resumo: Impacto da Análise de Sentimentos em redes sociais na sociedade moderna', 'Lucas Reis Abreu, Simara Vieira da Rocha, Geraldo Braz Júnior', '2017', 'Análise de sentimentos, impactos sociais, polaridade, opiniões', 'Devido ao avanço das mídias sociais observou-se um enorme crescimento de dados gerados e armazenados diariamente nesses ambientes. Dentro de tais redes sociais os usuários podem expressar opiniões próprias sobre diversificados assuntos, e é nesta esfera que atua a Análise de Sentimentos. Com a alta inclusão digital fornecida pela difusão da tecnologia, organizações e empresas voltaram sua atenção para as mídias digitais, procurando identificar dentro dos comentários dos usuários, características de seu interesse, como um produto está sendo recebido ou quais melhorias podem ser aplicadas sobre ele, por exemplo. A análise de sentimentos será responsável por classificar como positivo ou negativo (também chamado de polaridade) aquele comentário.', 'https://petcompufma.org/documents/Impacto-da-An%C3%A1lise-de-Sentimentos-em-redes-sociais-na-sociedade-moderna.pdf'),
(7, 'Resumo: Reformulação do site PET Computação, com ênfase na gestão do conteúdo', 'Micael Machado Gomes, Gabriel Phelipe Costa Freitas, Geraldo Braz Júnior', '2017', 'ENGENHARIA DE SOFTWARE, RECURSO, INTERFACE.', 'O PET de computação desenvolve no âmbito acadêmico atividades e projetos que buscam a melhoria do ensino superior, muitas vezes usando ferramentas para ampliar seu poder de mudança. Desse modo, o grupo pode executar seus serviços em ambientes onlines tal qual o site do PET de computação, porém a má gestão do mesmo pode levar a problemas simples como a poluição visual no layout da página e a falta de dinâmica no giro de informações. Nesse sentido, promovemos a reformulação e revitalização do site do PET de Computação, de forma a torná-lo mais efetivo para os alunos do curso e também servir como base para reformulação de conteúdo de outros grupos PET.', 'https://petcompufma.org/documents/Reformulacao-do-site-PET-computacao-com-enfase-na-gestao-do-conteudo.pdf'),
(8, 'Resumo: Uma abordagem competitiva para o estímulo ao aprendizado', 'Lucas Reis Abreu, Anderson Silva, Bruno Eduardo, Daniel Soares Carvalho, Diego Oliveira, Eduardo Roger, Gabriel Monteles, Hugo Gois, Marcos Vinicius, Phillipe Mendonça, Rodrigo Garcês, Rodrigo Nascimento, Tarcio Almeida, Victor Henrique, Geraldo Braz Junior', '2017', NULL, 'Transmitir o conhecimento apropriado de um determinado conteúdo sempre é acompanhado de desafios e o maior deles é ter a garantia que os alunos realmente absorveram a matéria lecionada de forma eficaz. Em vista de tal disputa, o grupo do Programa de Educação Tutorial de Ciência da Computação (PETComp) da Universidade Federal do Maranhão (UFMA), apresenta através deste trabalho uma proposta de abordagem competitiva metodológica para estruturação de competições envolvendo temáticas presentes no curso, tais como programação, robótica e jogos com a finalidade de subsidiar práticas de ensino, pesquisa e extensão.', 'https://petcompufma.org/documents/Uma-abordagem-competitiva-para-o-estimulo-ao-aprendizado-.pdf'),
(9, 'Resumo: Plataforma gamificada de auxílio para exames de POSCOMP e ENADE', 'Lucas Reis Abreu,  Anderson Silva,  Bruno Eduardo, Daniel Soares Carvalho, Diego Oliveira, Eduardo Roger, Gabriel Monteles, Hugo Gois, Marcos Vinicius, Phillipe Mendonça, Rodrigo Garcês, Rodrigo Nascimento, Tárcio Almeida, Victor Henrique, Geraldo Braz Junior', '2017', NULL, 'Testes como ENADE e POSCOMP (exame de ingresso na pós graduação do curso de computação) são constantemente realizados pelos discentes do curso, visando melhorar sua carreira profissional. Em prol de ajudar estes alunos, o Programa de Educação Tutorial de Ciência da Computação (PETComp) da Universidade Federal do Maranhão (UFMA) se propôs a construir uma plataforma gamificada denominada COMPET, cuja proposta é auxiliar os estudantes do curso e interessados nesta área de uma forma dinâmica, interativa e mais atrativa, visando melhorar seu desempenho nos respectivos exames citados através de um jogo de perguntas e respostas, na qual as perguntas foram retiradas de provas anteriores do ENADE e POSCOMP, além de questões temáticas elaboradas pelos próprios docentes da universidade.', 'https://petcompufma.org/documents/Plataforma-gamificada-de-aux%C3%ADlio-para-exames-de-POSCOMP-e-ENADE.pdf'),
(10, 'Artigo: Melhoria da Grade Curricular do Curso de Ciência da Computação da Universidade Federal do Maranhão: uma Abordagem Analítica', 'Anderson S. Fonseca, Eduardo R. S. Nascimento, Marcos Vinicius C. Gomes, Geraldo Braz Junior', '2017', NULL, 'A atual grade curricular do curso de Ciência da Computação da Universidade Federal do Maranhão (UFMA) não sofre atualizações desde o ano de 2007, o que é bastante tempo em se tratando de um curso com ênfase tecnológica. Logo, faz-se necessário uma revisão que permita atender as atuais expectativas de mercado de trabalho e também em relação a pesquisa.', 'https://petcompufma.org/documents/Melhoria-da-grade%20curricular-do-curso-de-ciencia-da-Computacao-da-Universidade-federal-do-maranhao-uma-abordagem-analitica.pdf'),
(11, 'Artigo: BodyRating: Uma proposta para anotção de silhueta corporal para avaliação de autopercepção', 'Anderson S. Fonseca, Victor H. B. de Lemos, Artur A. Silva, Geraldo Braz Junior,  Anselmo C. Paiva, Antonio A. M. da Silva', '2017', NULL, 'Atualmente, a aparência é de grande importância na vida de muitos e a forma que pessoas avaliam a própria imagem pode levar a diversos transtornos de autopercepção. Avaliar o nível desses transtornos levou a proposta da ferramenta BodyRating que anota a classificação de modelos 3D de pacientes voluntários feita por especialistas da área levando em consideração a Escala de Silhuetas. A ferramenta foi apresentada e percebeu-se uma grande aceitação da mesma. Após a anotação dos modelos 3D, os dados coletados serão utilizados como base para o desenvolvimento de uma ferramenta de classificação automática que é uma futura proposta de auxílio a especialistas.', 'https://petcompufma.org/documents/BodyRating-Uma-proposta-para-anotacao-de-silhueta-corporal-para-avaliacao-de-autopercepcao.pdf'),
(12, 'Artigo: O Uso de Competições como Ferramenta de Ensino e Fortalecimento do Aprendizado dentro do Curso de Ciência da Computação', 'Lucas Reis Abreu, Daniel Soares Carvalho, Diego Oliveira, Geraldo Braz Junior', '2017', NULL, 'Difundir o conhecimento de um conteúdo sempre apresenta desafios e o maior deles é ter a garantia de que os alunos realmente absorveram a matéria lecionada de forma prática. Em vista deste desafio, o grupo do Programa de Educação Tutorial de Ciência da Computação (PETComp) da Universidade Federal do Maranhão (UFMA), apresenta através deste trabalho uma proposta metodológica para realização de competições envolvendo assuntos de programação, robótica e jogos com a finalidade de subsidiar práticas de ensino, pesquisa e extensão.', 'https://petcompufma.org/documents/O-Uso-de-Competicoes-como-Ferramenta-de-Ensino-e-Fortalecimento-do-Aprendizado-dentro-do-Curso-de-Ciencia-da-Computacao.pdf'),
(13, 'Artigo: COMPET: Um software de Integralização do Curso de Ciência da Computação', 'Bruno Eduardo Silva Ferreira, Hugo Gois Santos, Lucas Reis Abreu,  Tarcio Almeida Lima, Rodrigo do Nascimento Siqueira, Jefferson Pereira Diniz, Phillipe Idivaldo Mendonça Silva, Victor Henrique Bezerra de Lemos, Geraldo Braz Junior', '2017', NULL, 'Os graduandos de Ciência da Computação deparam-se constantemente com testes, sejam eles através do ENADE ou para ingresso na pós-graduação (POSCOMP) ou mesmo através de provas de concursos caso opte por esse tipo de carreira. O COMPET é uma plataforma, cuja proposta é o auxílio a aprendizagem de estudantes de computação e interessados nesta área de forma interativa e atrativa melhorando seu desempenho por meio de questões retiradas do banco de provas do ENADE, POSCOMP e também perguntas elaboradas por professores da UFMA. Esta plataforma funciona de forma com elementos de gamification, onde ao ter êxito em responder um estipulado número de questões corretamente o usuário poderá subir de nível e ser gratificado com troféus a cada grupo de questões (fases) concluídas, ganhando assim pontos e petcoins (moeda utilizada dento da plataforma para comprar dicas). O objetivo da ferramenta consiste em além de preparar os alunos para o exame do POSCOMP, também servir à de orientação em suas carreiras profissionais, e ainda como forma de avaliação do curso. Através desta, será possível auxiliar os discentes no reforço de conteúdos que não foram tão bem absorvidos em sala de aula. Com a ferramenta construída, a mesma foi pré-avaliada com um grupo de discentes do curso de Ciência da Computação e foi constado aceitação pela comunidade acadêmica, tanto na finalidade de auxiliar o aprendizado quando na capacidade de desenvolver continuamente o aprendizado dos interessados.', 'https://petcompufma.org/documents/COMPET-Um-software-de-Integralizacao-do-Curso-de-Ciencia-da-Computacao.pdf'),
(14, 'Artigo: Estímulo ao pensamento computacional e a divulgação dos grupos PET UFMA: Desenvolvimento de WebPages como prática interdisciplinar', 'Hugo G. Santos ,Celielma Costa, Lucas R. Abreu, Eduardo R. S. Nascimento, Geraldo B. Junior', '2017', NULL, 'Buscando dar visibilidade aos trabalhos realizados pelos grupos PETs (Programa de Educação Tutorial), este trabalho aborda a experiência multidisciplinar de ensinar e implantar desenvolvimento e manutenção de websites para grupos PET das áreas sociais e humanas. Visto que o PET de Ciência da Computação esta intrinsecamente ligado aos meios de interação digital e visando a integração dos demais grupos, acolhemos a tarefa com dedicação, tendo conhecimento que os envolvidos eram leigos ou possuíam pouca base em relação a interface e ao domínio das diversas funcionalidades do WordPress, plataforma escolhida como base por sua manipulação intuitiva. Utilizando uma metodologia aberta ao diálogo, uma abordagem construtivista, slides demonstrativos e incentivando a equipe a manipular a plataforma, observamos o interesse individual ser demonstrado ao executarem as instruções pedidas. Muitos indo além do que lhes seria ensinado – o que nos possibilitou, com grande satisfação, aprofundar o conteúdo. Logo, podemos dizer que alcançamos resultados efetivos. Houve grande troca de informações, muitos questionamentos e, de fato, se tornaram uma experiencia enaltecedora para todos envolvidos.', 'https://petcompufma.org/documents/Estimulo-ao-pensamento-computacional-e-a-divulgacao-dos-grupos-PET-UFMA-Desenvolvimento-de-WebPages-como-pratica-interdisciplinar.pdf'),
(15, 'Artigo: Acompanhamento de Discentes: A monitoria como forma de incentivo e motivação da disciplina de Algoritmos I', 'Nelia Cantanhede Reis, Ednara Aparecida dos Santos Pereira, Gabriel Phelipe Costa Freitas, Vinicius Augusto Cardoso Reis, Geraldo Braz Junior', '2017', NULL, 'Este artigo tem como objetivo analisar de forma parcial sob o ponto de vista de alunos e professor as contribuições na aprendizagem da disciplina de Algoritmos I por meio de atividades de monitoria. Nossa abordagem envolve a aplicação de atividades e desafios que despertam o interesse do aluno em programar, também foram utilizadas plataformas que facilitam o aprendizado. Os dados foram obtidos através de questionários aplicados aos alunos e entrevista semiestruturada com o professor da disciplina, assim, foi constatado que essas atividades de fato têm impactos na aprendizagem. Os resultados obtidos mostram que a maioria dos estudantes foi de fato motivada.', 'https://petcompufma.org/documents/Acompanhamento-de-Discentes-a-monitoria-como-forma-de-incentivo-e-motivacao-da-disciplina-de-Algoritmos-I.pdf'),
(16, 'Artigo: Educação Tutorial em Ciência da Computação: uma proposta de sistematização', 'Julia Manayra da S. Ferreira, Jorge Luis M. Ribeiro, Aristóteles T. de Freitas Júnior, Gabriel Garcez Barros Sousa, Italo Francyles Santos da Silva, Hugo Gois Santos, Matheus Chaves Menezes, Artur Albuquerque Silva, Bruno Eduardo Silva Ferreira, Lucas Gabriel Rezende de Jesus, Victor Henrique Bezerra de Lemos , Antônio de Jesus Moraes Neto , Alexandre C. M de Oliveira', '2015', NULL, 'No intuito de proporcionar a formação acadêmica ampla e de qualidade, o Programa de Educação Tutorial (PET) é um modelo indissociável de ensino, pesquisa e extensão, que preza também por valores de cidadania e consciência social. Apesar de existir desde a década de 90, com o nome de Programa Especial de Treinamento, e ter se expandido para mais de 37 grupos na área de Computação, pouca ou nenhuma literatura tem sido produzida com intuito de prover uma base metodológica de atuação desses grupos. Este artigo descreve métodos e práticas que têm sido utilizados com êxito pelo PET de Ciência da Computação da Universidade Federal do Maranhão (PETComp/ UFMA) no desenvolvimento de suas atividades, aprimorados ao longo de seus oito anos de existência.', 'https://petcompufma.org/documents/Educacao-Tutorial-em-Ciencia-da-Computacao-uma-proposta.pdf'),
(17, 'Artigo: XSCERT: O Ponto de Encontro dos Grupos PET da UFMA', 'Alex Newman Veloso dos Santos, Dayson Newton Corrêa Rodrigues do Nascimento, Eduardo Dorneles Ferreira de Souza, Lázaro Henrique de Carvalho Marques e Alexandre César Muniz de Oliveira', '2014', NULL, 'A Educação Tutorial tem em seu escopo de desenvolvimento atividades de pesquisa, ensino e extensão que complementam a educação de seus alunos. Uma grande maioria destas atividades resulta em eventos abertos à comunidade acadêmica. Por sua vez, o gerenciamento destes eventos envolve inscrição, controle de frequência, comunicação com os participantes, certificação e avaliação da atividade. Com o objetivo de incentivar a produção de softwares aplicativos com tecnologia Web, o PET de Ciência da Computação tem desenvolvido uma série de atividades envolvendo pesquisa de exploração e minicursos sobre tecnologias para desenvolvimento de sites e aplicativos Web. Uma das iniciativas foi desenvolver um sistema de eventos, aberto para grupos acadêmicos da UFMA, como forma de facilitar o gerenciamento de algumas atividades e aproximar os grupos PET da UFMA. Este sistema foi posteriormente batizado de XSCERT.', 'https://petcompufma.org/documents/xscert-final.pdf'),
(18, 'Resenha: Crítica de “Futuro: O imaginado e o real”', 'Rodrigo Kanehisa', '2014', NULL, 'O texto começa citando um artigo que trata deste assunto e segue analisando os motivos pelo qual isso ocorre. Com o uso de imagens o autor mostra ao leitor o futuro imaginado em 1900 para o longínquo ano 2000, estas se mostram estranhas para o leitor do século 21, pois o que se vê é um mundo onde toda a tecnologia é baseada em inventos do início do século 20. Percebe-se que este mundo é de fato não o futuro como conhecemos, mas ironicamente é um retrato da era de onde veio.', 'https://petcompufma.org/documents/Resenha-Futuro-O-Real-e-o-Imaginada.pdf'),
(19, 'Resenha: Crítica de “A Tradução Universal e os Call Centers”', 'Gabriel Garcez Barros Sousa', '2014', NULL, '“A Tradução Universal e os Call Centers” (http://boletim.de/silvio/a-traduo-universale-os-call-centers/), de Sílvio Meira, é um texto sobre o estado dos tradutores universais atualmente e alguns dos impactos que um tradutor universal pode acabar tendo na sociedade.', 'https://petcompufma.org/documents/Resenha-a-traducao-universal-e-os-call-centers.pdf'),
(20, 'Resenha: Crítica de “Empresas em redes, riscos também”', 'Daniela de Sousa Costa', '2014', NULL, 'Em “Empresas em redes, riscos também” (blog Dia a Dia, Bite a Bite , 2014), Silvio Meira discorre acerca da postura adotada por empresas de todo o mundo perante a um novo cenário criado pelo surgimento dos sistemas em rede e que no qual estas têm assumido uma posição de vulnerabilidade considerável.', 'https://petcompufma.org/documents/Resenha-nem-tao-longe.pdf'),
(21, 'Resenha: Crítica de “Até onde vai a internet?”', 'Julia Manayra da Silva Ferreira', '2014', NULL, '“até onde vai a internet?”, do professor Silvio Meira, aborda a internet em si e os caminhos que a mesma pode tomar. Nos leva a uma interessante viagem pelo que já aconteceu e dentro da história e os passos dados da internet até que ela se tornasse o que é hoje, além de nos levantar alguns questionamentos referentes à sua utilização e manutenção.', 'https://petcompufma.org/documents/Resenha-Critica-do-artigo-sociedade-paralela.pdf'),
(22, 'Artigo: O Impacto das Atividades do Grupo PET no Aprimoramento de Soft Skills Requeridos pelo Mercado de Computação do Maranhão: Uma Análise da Visão dos Discentes', 'Arthur Passos, André Barreto, Brenno Nascimento, Felipe Silva, Gabriel Costa, Yandson Costa, Davi Viana, Luis Rivero', '2021', NULL, 'O profissional de computacão precisa adquirir as mais variadas habilidades para se manter competitivo no mercado de trabalho. Entre essas habilidades, as denominadas soft skills (ou habilidades não técnicas) são atributos pessoais  que  permitem  ao  indivíduo  desempenhar  uma boa interação com o mundo ao seu redor. Nesse contexto, o Programa de Educação Tutorial (PET) surge como uma alternativa para desenvolver tais habilidades durante o ensino superior. No entanto, existem poucas análises sobre como um discente pode desenvolver soft skills durante a realização de atividades no âmbito do PET. Neste artigo, através de um formulário, foi obtida a percepcção dos discentes sobre o impacto das atividades realizadas no PET para o desenvolvimento de soft skills, considerando o contexto do estado do Maranhão. Os resultados apontam parao impacto positivo das atividades do programa para este fim, além de identificar oportunidades de melhoria.', 'https://sol.sbc.org.br/index.php/wei/article/view/15930/15771'),
(23, 'Artigo: Quando os Discentes se Expressam: Um Relato de Experiência da Criação de um Podcast para Aumentar o Engajamento e Troca de Conhecimento em Tempos de Pandemia', 'Carlos Silva, Kennedy Nunes, Nathasha Pinto, Maikon Costa, Alana Araújo, Simara Rocha, Geraldo Braz Junior, Luis Rivero', '2021', NULL, 'Melhorar o engajamento de discentes e facilitar o acesso à informação têm se tornado mais relevantes no contexto educacional. Em virtude do isolamento social gerado pela pandemia da COVID-19, recursos didáticos como podcasts e vídeos podem ser explorados para alcançar este objetivo. Como intuito manter os discentes atualizados e engajados durante o ensino remoto, o grupo PETComp da Universidade Federal do Maranhão montou uma equipe para desenvolver um podcast sobre conteúdos relacionados a Tecnologia da Informação (TI). Este artigo apresenta o processo de produção dos episódios do podcast. Após a preparação do material e lançamento do podcast em plataformas digitais, foi coletada a opinião dos discentes sobre o mesmo através de um questionário. Os resultados indicam que o podcast contribuiu para disponibilizar conteúdos construídos pelos discentes de forma descontraída, permitindo a atualização em temas relevantes e o engajamento dos ouvintes.', 'https://sol.sbc.org.br/index.php/wei/article/view/15903/15744'),
(24, 'Artigo: Quando a Aluna se Torna a Mestre: Um Relato da Experiência de Alunas de Graduação Aplicando Dinâmicas de Ensino de Computação para Alunas de Ensino Médio', 'Nathasha Pinto, Alana Araujo, Estephane Mendes, Giovanna Pavani, Karla Silva, Raimundo Neto, Katia Salles, Luis Rivero', '2020', NULL, 'O quantitativo de mulheres nas carreiras e cursos das áreas de Computação e Tecnologias é baixo se comparado ao quantitativo de homens. Para incentivá-las a entrar em cursos de exatas, vários projetos de extensão têm sido executados. Nesse contexto, o presente artigo relata os resultados da aplicação de uma   gincana   em   que   foram   realizadas   atividades   de   ensino   envolvendo computação plugada e desplugada.  As atividades e o material preparado foram escolhidos e adaptados por alunas do curso de ciência da computação da Universidade Federal do Maranhão com o intuito de encorajar alunas de ensino médio.  Como resultado desta experiência, foi possível coletar opiniões sobre o processo de criação da gincana por parte das graduandas a avaliação da mesma por parte de alunas de ensino médio.', 'https://sol.sbc.org.br/index.php/wei/article/view/11125/10996'),
(25, 'Artigo: Aplicando Técnicas de Elicitação de Requisitos durante uma Disciplina para a Concepção de um Sistema de Informação: Um Relato de Experiência', 'Yandson de Jesus Saraiva Costa, Igor Rafael Barbosa Estrela, Micael Machado Gomes, Davi Viana dos Santos, Luis Jorge Enrique Rivero Cabrejos', '2020', 'Engenharia de Requisitos, Sistema de Informação, Relato de Experiência.', 'Técnicas de elicitação de requisitos são aplicadas para identificar as necessidades dos diferentes stakeholders no desenvolvimento de software. No entanto, engenheiros de software novatos encontram dificuldades ao aplicar estas técnicas na prática. Este artigo apresenta um relato de experiência sobre a combinação de técnicas de elicitação de requisitos e uma análise de opiniões dos alunos que aplicaram estas técnicas em um projeto real. Os resultados indicam: a aceitação da atividade formadora durante a disciplina; que os alunos se sentiram motivados a pesquisar mais sobre as técnicas para escolher a mais apropriada ao contexto do problema sugerido; e que mais material de apoio é necessário para ajudar na replicação das técnicas.', 'https://periodicos.set.edu.br/exatas/article/view/8809/4352'),
(26, 'Artigo: Modelo Distribuído de Cooperação Multi-grupo através de uma REST API na Gestao de Informação do Site PET UFMA', 'Micael Machado Gomes, Antonio Moreira Pinto, Gabriel Phelipe C. Freitas, Geraldo Braz Junior', '2018', NULL, 'Este trabalho aborda deste o reprojeto do site PET UFMA até suas fazes de implementação, conforme as novas mudanças arquiteturais atribuídas à mesma. Estas vão desde a proposta de uma nova arquitetura baseada em um modelo distribuído de cooperação entre os Grupos PET, até a construção de plugins WordPress que dão suporte. Tudo isso sustentado pela premissa que consiste em dividir a responsabilidade, que hoje é de um grupo, a todos.', 'http://sistemas.deinf.ufma.br/anaisjim/artigos/2018/201828.pdf'),
(27, 'Artigo: Adoção de Práticas EaD Como Forma de Capacitação e Aperfeiçoamento Durante a Quarentena', 'José Durand, Eduarda Chagas, Arthur Passos, Carlos Vinicius Silva Da Silva, Daniel Pinto, Gabriel Sousa, Kennedy Nunes, Maikon Keslley Costa, Pedro Arthur Freitas Dias, Luis Rivero', '2020', NULL, 'Diante do cenário desta pandemia, uma solução possível para a\r\ncarga total de trabalho estabelecida por vários programas universitários e\r\nde estágio é a educação à distância. A qualificação do EAD é uma abordagem\r\nalternativa porque permite um melhor aproveitamento da equipe durante o\r\nreinício das atividades habituais.', 'https://petcompufma.org/jim/anexos/anais/eJIM_2020_paper_7.pdf'),
(28, 'Artigo: Criando uma Revista Interativa para Divulgar Histórias de Mulheres na Computação', 'Guilherme Silva, Daniel Pinto, Karla Silva, Gabriel Costa, Jadiel Costa, Maikon Costa, Luis Rivero', '2020', NULL, 'O presente artigo apresenta o progresso de um projeto que visa utilizar um modelo interativo de revista digital com o propósito de disseminar a história e as conquistas de personalidades femininas em áreas da computação.', 'https://petcompufma.org/jim/anexos/anais/eJIM_2020_paper_8.pdf'),
(29, 'Artigo: Peça em Casa: Desenvolvimento de Um Aplicativo para Apoiar o Isolamento Social em Tempos de Pandemia', 'Gabriel Sousa, Alana Araujo, Jose Durand, Eduarda Chagas, Luis Dias, Natasha Pinto, Ricardo Anchieta, Luis Rivero', '2020', NULL, 'Para conter a disseminação do vírus COVID-19, vários estados têm proposto medidas de isolamento social. Para evitar que os cidadãos saiam de casa, foi desenvolvido o aplicativo “Peça em Casa”. O aplicativo publicado fornece informações sobre estabelecimentos que possuem serviço de delivery, e caso seja necessário, fornece informações sobre lotação de estabelecimentos.', 'https://petcompufma.org/jim/anexos/anais/eJIM_2020_paper_5.pdf'),
(30, 'Artigo: Análise de Ferramentas de Gerenciamento para Testes de Software: Propondo uma Alternativa para Realidade Local', 'Dayanne Gomes, Kennedy Anderson, Carlos Silva, Estephane Mendes, Luís Dias, Pedro Freitas, Geraldo Braz, Luis Rivero', '2020', NULL, 'Muitas ferramentas buscam auxiliar os testadores de software no gerenciamento de casos de teste seja automatizando processos ou gerando relatórios de projetos. Contudo, muitos problemas ainda não foram resolvidos pelas ferramentas disponíveis. Assim, um estudo comparativo foi realizado a fim de propor uma alternativa ao ferramentas existentes.', 'https://petcompufma.org/jim/anexos/anais/eJIM_2020_paper_9.pdf'),
(31, 'Artigo: Adaptando a Recepção de Calouros ao Contexto Virtual: Um Relato de Experiência do Uso de Tecnologias de Informação e Comunicação no Contexto da COVID-19', 'Luís Dias, Arthur Passos, Gabriel Costa, Guilherme de Carvalho, Kennedy Nunes, Alyson Silva, Gabriel Silva, Maikon Costa, Simara Rocha, Anselmo Paiva, Luis Rivero', '2021', NULL, 'Devido a pandemia de COVID-19, medidas de distanciamento social foram adotadas. Tendo em vista esse cenário, atividades de integração e ensino para alunos ingressantes na graduação precisaram ser adaptadas para o formato virtual. Nesse contexto, o grupo do Programa de Educação Tutorial em Computação da Universidade Federal do Maranhão criou o evento Acalorada Virtual. O evento foi organizado no período de dois meses e ocorreu durante três dias por meio de videoconferências. A Acalorada contou com atividades como apresentações sobre o curso e a universidade, dinâmicas interativas e palestras. Este artigo relata como o evento foi organizado pelos discentes veteranos utilizando diversas tecnologias de informação e comunicação gratuitas para que outras instituições interessadas possam replica-lo. Após uma avaliação através de questionário, os discentes participantes indicaram que o evento foi útil para sua formação e adaptação a nova rotina da universidade, e que as atividades realizadas foram bem desenvolvidas no ambiente virtual.', 'https://petcompufma.org/eacomp/Anais%202021/Adaptando%20a%20Recepc%C2%B8ao%20de%20Calouros%20ao%20Contexto%20Virtual%20Um%20.pdf'),
(32, 'Artigo: Qual o Impacto de Aplicar Novas Metodologia no Processo Seletivo do PET? Um Relato de Experiência do Processo Seletivo do PET de 2019.2', 'Alana Araújo, Gabriel S. Costa, J. R. Durand, Arthur Passos, Pedro Dias, Karla Silva, Luis Rivero  ', '2020', 'PROCESSO SELETIVO, CANDIDATO, CURSOS, APLICAÇÃO', 'Este artigo analisa os impactos de aplicar novas metodologias no processo seletivo para novos integrantes de um grupo PET. Procurava-se uma forma de filtrar melhor os participantes para que estes fossem capazes de se adaptar melhor ao fluxo de trabalho do PETCOMP. Para isso, foi aplicada uma nova metodologia que tinha como base três etapas de avaliação com o objetivo de verificar como os participantes lidam com tais situações e permitindo ao grupo melhor avaliar diversos aspectos dos candidatos. Ao final, foi possível notar que a metodologia trouxe benefícios a partir da aplicação, mostrando resultados satisfatórios tanto para o\r\ngrupo quanto para os candidatos.\r\n', 'https://petcompufma.org/documents/2020-ENEPET-Este-artigo-analisa-os-impactos-de-aplicar-novas-metodologias-no-processo-seletivo.pdf'),
(33, 'Artigo: Organização de um Evento de Computação na Visão de Petianos: Um relato de Experiência', 'Gabriel Marques, Giovanna Pavani, Jadiel Costa, Nathasha Pinto, Pedro H.\r\nCampos, Eduarda Chagas, Luis Rivero', '2020', 'ORGANIZAÇÃO, EVENTO, COMPUTAÇÃO, EXPERIÊNCIA, Organização, Evento, Computação, Experiência', 'O presente artigo relata a experiência de organizar e realizar a Escola Regional de Computação (ERCEMAPI), através de colaborações entre a Universidade Federal do Maranhão (UFMA) e o PET computação. O trabalho visa mostrar as tarefas desenvolvidas por integrantes do grupo e quais os métodos utilizados para atrair o público que em sua maioria eram alunos de graduação dos cursos de Engenharia e Ciência da computação. Tais alunos buscavam nas palestras, minicursos e oficinas\r\numa série de experiências para abranger seus conhecimentos. Foi possível ainda\r\nestabelecer parcerias entre o PET, a comunidade acadêmica de computação e\r\ntrazer a experiência de organizar um evento deste porte ao grupo, capacitando seus integrantes, que podem realizar ainda mais atividades da mesma linha.', 'https://petcompufma.org/documents/2020-ENEPET-Organiza%C3%A7%C3%A3o-de-um-Evento-de-Computa%C3%A7%C3%A3o-na-Vis%C3%A3o-de-Petianos.pdf'),
(34, 'Artigo: Developing a Checklist for Evaluating Virtual Learning Environments Through the Analysis of Evaluation Reports from an Educational Organization', 'Kennedy Nunes, Arthur Passos, João Santos, Yandson Costa, José Durand, Mizraim Mesquita, Paola Trindade, Elza Bernardes, Rayanne Silveira, Alana Oliveira, Davi Viana, Ana Emilia Figueiredo de Oliveira, Mario Teixeira, Luis Rivero', '2022', 'Chatbots, requirements, literature review, quality assurance ', 'Virtual Learning Environments (VLEs) and online educational resources have emerged as proposals for popularizing and democratizing learning by promoting access and inclusion of all types of users. There are several approaches to evaluate the quality of VLEs and their contents. However, despite initiatives to provide evaluation methods for meeting usability criteria and end-user educational needs, most evaluation methods focus on identifying problems within VLEs and their resources after they have been deployed. In this paper, we present the proposal of a checklist considering quality attributes from an end-user and pedagogical perspective found in real evaluation reports from the Directorate of Technologies in Education at Federal University of Maranhão. In all, 19 reports were analyzed identifying 34 verification items for evaluating different quality attributes in VLEs and educational resources. The checklist can be used for evaluating educational resources and VLEs before validating the developed software with the pedagogical team and releasing the courses. We are currently employing the proposed checklist for internal evaluations gathering usage data.', 'https://link.springer.com/chapter/10.1007/978-3-031-22131-6_28'),
(35, 'Artigo: Identifying Requirements and Quality Attributes from the Point of View of Users of Mobile Digital Libraries', 'José Meireles, Kennedy Nunes, Arthur Passos, João Santos, Yandson Costa, José Durand, Rayanne Silveira, Alana Oliveira, Davi Viana, Ana Emilia Figueiredo de Oliveira, Mario Teixeira, Luis Rivero', '2022', 'Mobile digital libraries, Feature analysis, App comments analysis, Software requirements, Quality attributes', 'Due to the COVID-19 pandemic there has been a significant growth in the adoption of online educational resources, including mobile digital libraries. Thus, several quality attributes have been indicated by both industry and academy for designing useful and usable digital libraries. Nonetheless, we are not aware of a complete list of requirements that could be met to develop high quality digital libraries in the mobile context. In this paper, we try to meet this gap by identifying features that digital libraries should provide. To do so, we carried out an analysis of 20 Brazilian mobile digital libraries in the market, identifying requirements that provide functionalities for users. Also, we analyzed app comments from the top rated and least rated mobile digital libraries apps, to extract quality attributes. In all, we identified 14 requirements through the analysis of the applications and 49 quality attributes considering the opinions on users’ comments. The list of requirements and quality attributes is useful to understand the users’ expectations and understand what to maintain or remove when designing and developing a mobile digital library.', 'https://link.springer.com/chapter/10.1007/978-3-031-17615-9_27'),
(36, 'Artigo: Enabling Pragmatic Software Testing Education in Brazil through anEducation Repository: An Initial Proposal', 'João Gomes, Kennedy Nunes, Luis Rivero, Davi Viana, Geraldo Braz Junior, João Almeida, Vandecia Fernandes, Simara Rocha, Aristófanes Silva', '2022', 'Software Testing, Computer Science Education, Repository', 'When teaching software testing, it is essential that the students have access to the practical application of the theoreticalconcepts regarding software testing techniques. Thus, it is important that support materials and real artifacts are available forthe practical application of the testing approaches. Despite this importance, undergraduate students from computer sciencecourses still face difficulties in the practical application of the contents covered in the classroom. In this work in progress, ourgoal is to support the learning process by offering artifacts that allows students to improve their practical skills in softwaretesting. For this, an analysis of the set of test techniques taught in classes and required by the job market was carried out. Wealso performed an analysis of the features of the repositories that provide support artifacts for teaching these techniques.Considering that the identified repositories are not in Portuguese, we present a high-fidelity prototype of a new Brazilianrepository, aggregating the identified artifacts and proposing new ones for supporting testing teaching.', 'https://sol.sbc.org.br/index.php/lique/article/view/19998/19826'),
(37, 'Artigo: Classificação de Estágios de Glaucoma Utilizando Volumes OCT e CNN3D', 'Matheus Levy, Marcos Melo Ferreira, Geraldo Braz Júnior, Marcus Vinicius Silva Lima de Oliveira, Gabriel Costa, Mario Freitas, Luis Rivero', '2022', NULL, 'Glaucoma é uma das doenças responsáveis pela cegueira. A detecção desta doença em estágios iniciais pode ajudar os pacientes em um tratamento para melhorar a qualidade de vida. Este estudo propõem a utilização de um método baseado em Deep Learning para fazer a classificação dos estágios do glaucoma em inicial, moderado/avançado e sem glaucoma. Para isso, utili- zamos a base GAMMA, composta por 100 pares de imagens, fundos de olho e volumes OCT. Para fazer a classificação deste tipo de dado tridimensional propomos a utilização de uma CNN 3D baseada nos princípios da DenseNet e usamos Transfer Learning. O melhor resultado alcançado foi 84% de ACC com 2 Classes e 67% com 3 Classes. Mesmo com resultados limitados a técnica se mostra como uma boa base para trabalhos futuros de melhorias.', 'https://sol.sbc.org.br/index.php/sbcas/article/view/21639/21463'),
(38, 'Artigo: O Impacto Das Monitorias Acadêmicas Na Formação De Alunos De Ciência Da Computação: Um Relato Do PETComp UFMA', 'Melquezedeque Costa, Maxwell Pires, Rick Santos, Luis Rivero', '2023', 'pesquisa, discentes, aprendizado, monitores', 'Este artigo relata a experiência do grupo PET de Computação da UFMA (PETComp) na realização de monitorias para os alunos do curso. Com um planejamento cuidadoso, as monitorias foram conduzidas de forma híbrida, combinando os formatos online e presencial para fornecer suporte personalizado aos estudantes. Foram aplicados formulários online tanto para os monitores quanto para os novos discentes, com o intuito de obter avaliações sobre o desempenho, relato e satisfação das monitorias. Foi constatado o impacto positivo das monitorias no apoio aos alunos, auxiliando-os a superar desafios acadêmicos e fortalecendo a comunidade educacional. O artigo convida os leitores a explorar como as monitorias do PETComp têm feito a diferença na vida acadêmica dos estudantes de Ciência da Computação, transformando desafios em oportunidades e promovendo um ambiente de aprendizagem enriquecedor.\r\n', 'https://even3.blob.core.windows.net/anais/658460.pdf'),
(39, 'Artigo: Explorando o Pensamento Computacional Através De Jogos Educacionais Desplugados', 'Joana Kuelvia de Araujo Silva, André Luiz Ribeiro de Araujo Lima, Sabryna Rodrigues Araujo, Adriano França Monteiro, Luis Jorge Enrique Rivero Cabrejos\r\n', '2023', 'PETComp, computação, ingressantes, abordagem prática', 'Os Jogos Desplugados são uma alternativa desenvolvida pelo PET de Ciência da Computação (PETComp) que visa introduzir os novos alunos aos conceitos de Pensamento Computacional e desenvolver habilidades essenciais ao curso de Computação. Muitos alunos ingressam sem conhecimento prévio de PC, e para combater esse desafio, o PETComp aplicou os jogos durante a Recepção dos Calouros 2023.1. Ao final das atividades, foi possível verificar uma maior compreensão dos conceitos por meio da abordagem prática dos jogos. Este artigo descreve o funcionamento de três desses jogos, apresenta o processo de aplicação e compartilha as percepções dos discentes sobre a eficácia dos mesmos. Conclui-se que é necessário dar continuidade a essas práticas, levando em consideração as sugestões dos alunos para futuras melhorias, para facilitar a jornada acadêmica dos ingressantes.\r\n', 'https://even3.blob.core.windows.net/processos/019cc300de1e433aae54.pdf'),
(40, 'Artigo: Proposing Usability-UX technologies for the design and evaluation of text-based chatbots', 'Malu Gabriele Silva Mafra, Kennedy Nunes, Simara Rocha, Geraldo Braz Junior, Aristofanes Silva ,Davi Viana, Williamson Silva, Luis Rivero', '2024', 'Inspection Checklist, Chatbots Evaluation, Usability, User Experience, Design Patterns', 'Chatbots are interactive systems that communicate using natural language with human users, via a textual interface or voice activation. These tools are useful for many spheres of business such as Customer Service, Sales, Education and Learning, Health and Entertainment. Recently, chatbots have become popular, with significant growth in the software industry, especially text-based chatbots. This is encouraging developers to create their own tools, as well as attracting efforts from researchers into this area. Despite this highlight, technologies to guarantee the quality of chatbots and user satisfaction are not keeping up with the growing demand for these tools. Considering this, there is a need to propose technologies capable of supporting developers and development teams in the process of building and evaluating chatbots. Therefore, this research proposes to develop artifacts applicable to the design and evaluation process of chatbots, based on quality attributes identified in systematic literature reviews related to Usability and User Experience (UX), due to the importance and impact that these aspects have on user satisfaction and the perceived quality of the system. The first artifact is the U2Chatbot inspection checklist, developed to assist development teams in the process of identifying defects in text-based chatbots. The second artifact is a set of interface design patterns, DP-U2Chatbot, containing useful examples to support developers in the process of building chatbots. The technologies were subjected to the necessary evaluations. The results of the empirical study regarding the U2Chatbot inspection checklist indicated that participants considered the technology useful for discovering defects in chatbots, however, ease of use could be improved. The participants\' experience discreetly influenced the effectiveness and efficiency of the technique, leading us to believe that professionals with a certain level of inspection experience can benefit more from the checklist. Regarding the evaluation of DP-U2Chatbot design patterns, the results generally indicated that the technology is easy to understand and useful in supporting the design of chatbots, helping to build better tools.', 'https://journals-sol.sbc.org.br/index.php/jis/article/view/3856/2575'),
(41, 'Artigo: O que impacta na qualidade de uso de bibliotecas digitais móveis? Definindo atributos de qualidade a partir da literatura e opinião dos usuários', 'Gabriel Oliveira, Anderson Lopes, José Melo, Rui Serra, Arthur Passos, Davi Viana, Luis Rivero', '2023', 'Bibliotecas Digitais M´oveis, Atributos de Qualidade, Requisitos, Checklist', 'Nos últimos anos, ocorreu um grande crescimento na adoção de recursos educativos online, incluindo as bibliotecas digitais móveis. Para atender melhor os usuários, é essencial que essas bibliotecas sejam fáceis de usar, tenham um bom poder computacional e sejam atualizadas regularmente. No entanto, nota-se a falta de definição de atributos de qualidade que direcionem o desenvolvimento dessas bibliotecas. Esta pesquisa tem o objetivo de coletar atributos de qualidade através da análise de artigos, uso de aplicativos de bibliotecas e comentários de usuários. Em cada etapa, fazendo análises de características, criou-se uma lista de atributos que foram associados, desenvolvendo um total de 42 requisitos. Com esse processo, gerou-se um checklist que permite avaliar e desenvolver bibliotecas digitais móveis e, ao final, ele foi aplicado em 2 aplicativos de bibliotecas digitais móveis escolhidas. Ao analisar os atributos identificados durante a avaliação, foram obtidos resultados compatíveis com as avaliações dos usuários.', 'https://seer.ufrgs.br/index.php/renote/article/view/134387/89324'),
(42, 'Artigo: Identificando oportunidades de melhoria em uma biblioteca digital móvel à partir da aplicação de inspeção de usabilidade', 'Arthur Passos, João Davi Santos Passos, Kennedy Nunes, Rayanne Silveira, Davi Viana, Alana Oliveira, Mario Teixeira, Luis Rivero', '2023', 'Checklist, Inspeção, Usabilidade, Biblioteca Digital, Aplicativos Móveis', 'O aumento na adoção de recursos educacionais online tem despertado o interesse por novas ferramentas de apoio ao ensino remoto, incluindo bibliotecas digitais móveis. Assim, a usabilidade tem se tornado um dos atributos de qualidade mais relevantes indicado pela indústria e pela academia para projetar bibliotecas digitais úteis e fáceis de usar. No entanto, não há muitos exemplos da aplicação prática de avaliações de usabilidade em bibliotecas digitais no contexto móvel. Neste artigo, foi aplicada uma proposta de checklist de avaliação de usabilidade específico para bibliotecas digitais móveis, visando identificar defeitos em um sistema real. Assim, foi avaliada uma biblioteca digital para a área da saúde contendo recursos educacionais no contexto de Urgências Odontológicas. A avaliação ocorreu seguindo as etapas: planejamento, detecção, coleção e discriminação de defeitos, apontando 20 defeitos e diversas oportunidades de melhoria na biblioteca avaliada.', 'https://seer.ufrgs.br/index.php/renote/article/view/134384/89323');
INSERT INTO `trabalhos_publicados` (`id`, `titulo`, `autor`, `ano`, `palavras_chave`, `resumo`, `link`) VALUES
(43, 'Artigo: A Aplicação de Podcasts como Tecnologia de Apoio ao Ensino em Sala de Aula: Um Relato de Experiência no Contexto de Ensino de Engenharia de Software', 'Rodrigo Miranda Feitosa, Eduarda Chagas, Carlos Eduardo Portela Serra de Castro, Kennedy Nunes, Ivana Marcia Maia, Anselmo Paiva, Davi Viana, Luis Rivero', '2023', 'Metodologias Ativas, Podcast, Relato de Experiência, Tecnologias no Ensino', 'Metodologias ativas são estratégias de ensino que podem incentivar os estudantes a aprender de forma autônoma e participativa. Com objetivo de avaliar o impacto da produção e uso de Podcasts como uma metodologia ativa, este trabalho apresenta um relato de experiência em que Podcasts foram produzidos como parte das atividades de ensino em disciplinas de Engenharia de Software. Após a avaliação da metodologia pelos discentes, a maioria concordou com o impacto positivo da atividade no aprendizado de novos conceitos. Além disso, foram identificadas as oportunidades de melhoria para facilitar a adoção de Podcasts como: variabilidade de formatos de episódios gravados, criação de um repositório de episódios como material didático, revisão de textos científicos entre os discentes através de uma aprendizagem colaborativa, participação dos discentes em mais de um papel na produção do episódio, e estudo frequente de categorias de podcast ou modelos para inserção de outros elementos na montagem dos episódios.', 'https://seer.ufrgs.br/index.php/renote/article/view/137724/90908'),
(44, 'Artigo: Checklist para Avaliação de Aceitabilidade de Ambientes Virtuais de Aprendizagem em Termos da Usabilidade', 'Anderson Lopes, Gabriel Oliveira, José Melo, Rui Serra, Arthur Passos, Kennedy Nunes, Davi Viana, Luis Rivero', '2023', 'Ambientes Virtuais de Aprendizagem, Atributos de Qualidade, Checklist, Experiência do Usuário, Qualidade de Uso', 'A usabilidade e um fator que influencia na qualidade da Experiência do Usuário (UX) com o sistema. Embora esse atributo seja de extrema importância, há ainda carência de métodos que visam identificar as necessidades dos usuários e as falhas de usabilidade em Ambientes Virtuais de Aprendizagem (AVAs). Nesta perspectiva, o presente trabalho objetiva extrair atributos de qualidade por meio de artigos publicados e de comentários de usuários sobre AVAs utilizados em um teste de usabilidade. Nas etapas foram realizadas analises de características, para associar os atributos, criando uma lista com 36 atributos. Com isso, desenvolveu-se um checklist robusto para avaliação de aceitabilidade de AVAs com base na usabilidade, que ficou testado em dois AVAs, um AVA compulsório é um AVA comercial. Ao final, os resultados obtidos promovem a qualidade da UX e identificam opções de melhoria do ambiente que condizem com a necessidade do utilizador', 'https://seer.ufrgs.br/index.php/renote/article/view/137745/90927'),
(45, 'Artigo: Quando a Teoria é Aplicada: Um Relato de Experiência da Aplicação de Metodologias de Desenvolvimento de Sistemas Computacionais dentro do PETComp-UFMA', 'Italo Dovera, Matheus Bessa, Brenno Nascimento, Felipe Silva, Rafaela Gomes, Geraldo Braz Junior, Adriana Nogueira, Luis Rivero', '2022', 'Relato de Experiência, Processo de Desenvolvimento, Programa de Educação Tutorial, Metodologia de Ensino e Prática Aplicada', 'Na computação, existe um avanço rápido e constante de novas ferramentas de desenvolvimento de software, o que leva os profissionais da área ao aprimoramento também constante de seus conhecimentos sobre essas novas ferramentas. Porém, essa rápida evolução dificulta a escolha de uma metodologia eficiente aos times de desenvolvimento. Nesse contexto, este artigo visa relatar a experiência de desenvolver sistemas, além de apresentar ferramentas e metodologias que auxiliem grupos iniciantes em tal processo. A equipe do Programa de Educação Tutorial em Computação (PETComp) da Universidade Federal do Maranhão definiu um processo de treinamento e desenvolvimento, com funções divididas entre equipes de desenvolvimento e design. Ao todo, uma equipe de discentes com pouca experiência em desenvolvimento realizou atividades como: prototipação, reuniões de validação e aprendizagem de ferramentas. Como resultado, obteve-se a criação de sites para eventos, sites para o curso de graduação e aplicativos móveis. ', 'https://sol.sbc.org.br/index.php/wei/article/view/20824/20650'),
(46, 'Artigo: Tutorial para Futuras Cientistas: Um Relato de Cursos para a Disseminação da Participação de Mulheres na Área de Computação', 'Jackson S. Nascimento, Jéssica Cristina S. Nascimento, Pedro Alexandre F. França, João Victor C. Gonçalves, Katia de la Salles, Davi Viana, Aurea Melo, Luis Rivero', '2022', 'Relato de Experiência, Cursos de Computação, Mulheres na Computação', 'Vários são os estudos na literatura que apontam o público feminino como minoria nos cursos superiores da área de Tecnologia da Informação. Como consequência, inumerosas iniciativas surgiram para incentivar a entrada de mulheres para essas carreiras. Este artigo relata a elaboração de uma atividade de tutoriais, com um conjunto de minicursos estratégicos, na oitava edição do Encontro Acadêmico de Computação (EAComp), organizado pelo Programa de Educação Tutorial (PET) da Universidade Federal do Maranhão em 2021. O objetivo foi atrair o público feminino ao ingresso acadêmico no curso de Ciência da Computação. Também, este artigo apresenta a percepção das participantes sobre o impacto dessa atividade para o aumento e integração de mulheres no espaço acadêmico.', 'https://sol.sbc.org.br/index.php/wie/article/view/22365/22189'),
(47, 'Artigo: Criando uma solução automatizada para o controle de atividades em grupo PET', 'Anderson Leandro Fernandes Batalha, Sabryna Rodrigues Araujo, Vitor Gabriel Rodrigues Sousa, Juan Carlos Melo do Nascimento, Heloísa Jansen Ferreira Ribeiro, Victor José Beltrão Almajano Martinez, Breno Roberto Reis Vidigal, Luis Jorge Enrique Rivero Cabrejos', '2024', 'PET; planilha; gestão de tarefas.', 'As planilhas automatizadas são uma tecnologia essencial para o gerenciamento de informações, proporcionando a rápida realização de cálculos e a eficiente organização de dados (TAVARES, 2020). Devido à necessidade de controlar de maneira mais eficiente as atividades desenvolvidas dentro do grupo PET, foram idealizadas planilhas automatizadas para melhorar a gestão de tarefas da equipe, visando o aumento da produtividade e melhor organização das demandas. Neste artigo, apresenta-se o desenvolvimento e a implantação de uma planilha automatizada para controle das atividades do grupo PETComp da UFMA. Também foi avaliado o resultado da aplicação da planilha via questionário, no qual 12 de 13 petianos (92%) indicaram um impacto positivo da planilha automatizada em suas atividades. Este estudo visa analisar os efeitos gerados pela aplicação da planilha automatizada, podendo ser aplicado em outros grupos PET.', './assets/artigos/CRIANDO UMA SOLUÇÃO AUTOMATIZADA PARA O CONTROLE DE ATIVIDADES EM GRUPOS PET.pdf'),
(48, 'Artigo: Aplicando Uma Metodologia Colaborativa Para Trabalhos Dentro De Um Grupo Pet: Um Relato De Experiência No Petcomp - Ufma', 'Anderson Leandro Fernandes Batalha, Vitor Gabriel Rodrigues Sousa, Heloísa Jansen Ferreira Ribeiro, Victor José Beltrão Almajano Martinez, Francisco Roberto Cantanhêde Brito, Wenderson Arthur Dutra Oliveira, Wemerson Chagas De Miranda, Pedro Artur Oliveira Costa, José Guilherme Magalhães de Almeida, Luis Jorge Enrique Rivero Cabrejos', '2024', 'Ensino; Aprendizagem; Colaboração; Metodologia.', 'As atividades dos grupos PET (Programa de Educação Tutorial) enfatizam\r\nensino, pesquisa e extensão, essenciais para a formação acadêmica e profissional. Para atender\r\nàs demandas, é necessário um intenso aprendizado técnico, que pode ser desafiador quando\r\nrealizado de forma isolada, especialmente em grupos com alta rotatividade de membros. O\r\nPETComp-UFMA implementou uma metodologia colaborativa intergeracional, promovendo\r\ntransferência eficiente de conhecimentos entre os discentes. Este trabalho apresenta um relato\r\nsobre a aplicação dessa metodologia em projetos de desenvolvimento e ensino, destacando\r\nseus resultados preliminares.', './assets/artigos/APLICANDO UMA METODOLOGIA COLABORATIVA PARA TRABALHOS DENTRO DE UM GRUPO PET_ UM RELATO DE EXPERIÊNCIA.pdf'),
(49, 'Artigo: De Estudante Para Estudante: O Impacto Das Monitorias Acadêmicas Organizadas Pelo Petcomp Ufma Visando A Diminuição Da Evasão Estudantil', 'Victor José Beltrão Almajano Martinez, Juan Carlos Melo do Nascimento, Sabryna Rodrigues Araujo, Vitor Gabriel Rodrigues Sousa, José Guilherme Magalhães de Almeida, Luis Jorge Enrique Rivero Cabrejos', '2024', 'Monitorias; Acompanhamento; Discentes; Evasão;', 'A formação superior é essencial para o crescimento pessoal e social, oferecendo\r\nconhecimentos especializados e permitindo o desenvolvimento de habilidades fundamentais\r\npara diferenciação no mercado de trabalho, sucesso profissional e, a longo prazo, na formação\r\nde cidadãos como agentes da mudança. Entretanto, visualiza-se um alto índice de evasão nas\r\nfaculdades brasileiras em períodos iniciais, sobretudo em cursos da área de ciências exatas e\r\ntecnologias. Nesse contexto, o PETComp-UFMA implanta Grupos de Acompanhamento de\r\nDiscentes (GAD) para realizar monitorias nas matérias iniciais do curso ciência da\r\ncomputação, combatendo a evasão e incentivando os discentes a se engajarem no aprendizado\r\npara além da sala de aula. Assim, o presente artigo descreve o relato de experiência no\r\nacompanhamento do processo da ministração das monitorias, apresentando a metodologia\r\nutilizada, seus resultados e uma breve discussão mediante uma avaliação respondida pelos\r\ndiscentes participantes.\r\n', './assets/artigos/Monitorias.docx.pdf'),
(50, 'Artigo: Desenvolvimento De Um Sistema Com Dashboards Para Apresentação De Resultados De Projetos De Pesquisa Educacionais', 'Fabio Kauê Araujo da Silva, André Luiz Ribeiro de Araujo Lima, Paloma Santos Ferreira, Rick Eick Vieira Dos Santos, Francisco Roberto Cantanhêde Brito, Pedro Artur Oliveira Costa, Luis Jorge Enrique Rivero Cabrejos', '2024', 'Índices; Representações Visuais; Planilhas.', 'O constante acompanhamento do andamento e dos resultados de projetos de\r\npesquisa educacionais são de extrema importância, uma vez que possibilita o controle de\r\ndesempenho e qualidade do programa de forma transparente. Contudo, constantemente dados\r\nsão apresentados aos interessados de forma ineficiente e estática, dificultando a síntese de\r\ninformações e impossibilitando a personalização das buscas. Nessa perspectiva, dashboards\r\nsão representações visuais de dados essenciais de forma interativa, apresentando parâmetros e\r\níndices de forma a melhorar a compreensão das informações e auxiliar na tomada de decisões.\r\nLevando isso em consideração, o presente artigo descreve o desenvolvimento de um modelo\r\nde dashboard voltado para o cenário de projetos de pesquisa no contexto educacional,\r\napresentando a criação de uma planilha automatizada para extração dos dados, o projeto do\r\nsistema para hospedar o dashboard, assim como a implementação e validação dos resultados\r\ncom o cliente. O sistema apresentado foi instanciado com informações fictícias, podendo ser\r\nutilizado posteriormente para projetos de pesquisa em outros contextos visando a\r\nsimplificação da análise dos resultados obtidos pelos mesmos.\r\n', './assets/artigos/DESENVOLVIMENTO DE UM SISTEMA COM DASHBOARDS PARA APRESENTAÇÃO DE RESULTADOS DE PROJETOS DE PESQUISA EDUCACIONAIS.docx.pdf'),
(52, 'Artigo: Do Primeiro Contato à Permanência: Acalourada como Ferramenta de Integração ao PETComp', 'Anderson Leandro Fernandes Batalha, Amadeu Fernandes da Silva Neto, Ariel Batista Costa da Silva, Francisco Roberto Cantanhêde Brito, José Guilherme Magalhães de Almeida, Paulo Nixon Cantanhede dos Santos Saraiva, Wemerson Chagas de Miranda, Yan Felipe Buceles Pinto, Luis Jorge Enrique Rivero Cabrejos', '2025', 'Programa de Educação Tutorial; Acalourada; Calouro; Permanência Estudantil.', 'As atividades do PETComp (Programa de Educação Tutorial de Ciência da Computação da UFMA) integram ensino, pesquisa e extensão, sendo fundamentais para a formação dos discentes. Neste contexto, o presente trabalho destaca a participação do grupo nas Acalouradas, evento institucional de recepção de calouros, como estratégia de divulgação e fortalecimento do programa. A partir de formulários digitais e análise qualitativa das percepções dos participantes, observou-se que a Acalourada tem sido um ponto de contato inicial e decisivo para o ingresso no PETComp. Os resultados indicam que a atuação do grupo no evento contribui para o aumento do interesse, compreensão das atividades e redução da rotatividade de ingressantes, consolidando a ação como uma ferramenta eficaz de acolhimento e engajamento estudantil.', 'https://drive.google.com/file/d/1SWLdVJ76_7tl0F2awXLkPSsJqK5R_7ga/view'),
(53, 'Artigo: Planilhas Inteligentes: Transformando Organização em Automação Via Programação', 'José Guilherme Magalhães de Almeida, Anderson Leandro Fernandes Batalha, Francisco Roberto Cantanhêde Brito, Rochel Andrey dos Santos Costa, Rôberth Kauã Diniz Costa, Wenderson Arthur Dutra Oliveira, Carlos Guilherme Santos Rodrigues, Breno Roberto Reis Vidigal, Luis Jorge Enrique Rivero Cabrejos', '2025', 'Automação; Planilha; Apps Script.', 'O controle diário de atividades é essencial para a organização e o bom funcionamento de grupos acadêmicos como o PETComp (Programa de Educação Tutorial em Ciência da Computação). Este artigo apresenta a avaliação da implementação de uma planilha automatizada, criada com Google Sheets e Google Apps Script, com o objetivo de tornar o processo de registro de atividades mais eficiente, confiável e acessível. A automação foi modelada por meio de um fluxo de estados do sistema. A metodologia adotada para avaliação da ferramenta consistiu na aplicação de um questionário para os membros da equipe. Os dados coletados foram analisados com foco na percepção dos usuários sobre usabilidade, eficiência e adaptabilidade. Os resultados apontam ganhos significativos e se mostrou uma solução viável e eficiente para o gerenciamento das atividades diárias. A experiência demonstra como ferramentas de baixo custo podem ser aplicadas para otimizar processos rotineiros em contextos acadêmicos com recursos limitados.', 'https://drive.google.com/file/d/1SWLdVJ76_7tl0F2awXLkPSsJqK5R_7ga/view');
